-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Windurst_Woods/npcs/Tapoh_Lihzeh.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Tapoh_Lihzeh.lua",["SHA256"]="22c6b8c93fdfde813598f408afa25fc641d4f0d27f2cb06ab597c8a28ed95f4b",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Tapoh Lihzeh\n-- Starts & Finishes Repeatable Quest: Paying Lip Service\n-- !pos 51.011 -3.749 54.402 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- CHOCOBILIOUS\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('ChocobiliousQuest') == 1 and\n        npcUtil.tradeHas(trade, xi.item.PAPAKA_GRASS)\n    then\n        player:startEvent(229, 0, xi.item.PAPAKA_GRASS)\n\n    -- PAYING LIP SERVICE\n    elseif player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.PAYING_LIP_SERVICE) >= xi.questStatus.QUEST_ACCEPTED then\n        if npcUtil.tradeHas(trade, { { xi.item.BEEHIVE_CHIP, 3 } }) then -- beehive_chip\n            player:startEvent(479, 0, xi.item.BEEHIVE_CHIP, xi.item.REMI_SHELL, 0, 0)\n        elseif npcUtil.tradeHas(trade, { { xi.item.REMI_SHELL, 2 } }) then -- remi_shell\n            player:startEvent(479, 0, xi.item.BEEHIVE_CHIP, xi.item.REMI_SHELL, 0, 1)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local chocobilious = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n    local chocobiliousCS = player:getCharVar('ChocobiliousQuest')\n    local payingLipService = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.PAYING_LIP_SERVICE)\n\n    -- CHOCOBILIOUS\n    if chocobilious == xi.questStatus.QUEST_ACCEPTED and chocobiliousCS == 2 then\n        player:startEvent(230) -- after trading\n    elseif chocobilious == xi.questStatus.QUEST_ACCEPTED and chocobiliousCS == 1 then\n        player:startEvent(228, 0, xi.item.PAPAKA_GRASS) -- after first talk\n    elseif chocobilious == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(227, 0, xi.item.PAPAKA_GRASS) -- first talk\n\n    -- PAYING LIP SERVICE\n    elseif payingLipService == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(478, 0, xi.item.BEEHIVE_CHIP, xi.item.REMI_SHELL, xi.settings.main.GIL_RATE * 150, xi.settings.main.GIL_RATE * 200)\n    elseif payingLipService == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(477, 0, xi.item.BEEHIVE_CHIP, xi.item.REMI_SHELL, xi.settings.main.GIL_RATE * 150, xi.settings.main.GIL_RATE * 200)\n\n    -- STANDARD DIALOG\n    else\n        player:startEvent(437)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- CHOCOBILIOUS\n    if csid == 227 then\n        player:setCharVar('ChocobiliousQuest', 1)\n    elseif csid == 229 then\n        player:setCharVar('ChocobiliousQuest', 2)\n\n    -- PAYING LIP SERVICE\n    elseif csid == 477 and option == 1 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.PAYING_LIP_SERVICE)\n    elseif csid == 479 then\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.PAYING_LIP_SERVICE) == xi.questStatus.QUEST_ACCEPTED then\n            npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.PAYING_LIP_SERVICE, { fame = 10, title = xi.title.KISSER_MAKE_UPPER })\n        else\n            player:addFame(xi.fameArea.WINDURST, 10)\n        end\n\n        if option == 1 then -- remi_shell\n            npcUtil.giveCurrency(player, 'gil', 200)\n        else -- beehive_chip\n            npcUtil.giveCurrency(player, 'gil', 150)\n        end\n\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Umumu.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Umumu.lua",["SHA256"]="386b7706a384144710d308dd00ac734dfcc2b93d0b3470e99bcf2aec006b83c5",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Umumu\n--  Involved In Quest: Making Headlines\n-- !pos 32.575 -5.250 141.372 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n\n    if makingHeadlines == xi.questStatus.QUEST_ACCEPTED then\n        -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n        local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n        if utils.mask.getBit(prog, 4) then\n            player:startEvent(383) -- Advised to go to Naiko\n        elseif not utils.mask.getBit(prog, 3) then\n            player:startEvent(381) -- Get scoop and asked to validate\n        else\n            player:startEvent(382) -- Reminded to validate\n        end\n    elseif makingHeadlines == xi.questStatus.QUEST_COMPLETED then\n        local rand = math.randomInt(1, 3)\n\n        if rand == 1 then\n            player:startEvent(385) -- Conversation after quest completed\n        elseif rand == 2 then\n            player:startEvent(386) -- Conversation after quest completed\n        elseif rand == 3 then\n            player:startEvent(414) -- Standard Conversation\n        end\n    else\n        player:startEvent(414) -- Standard Conversation\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 381 then\n        npcUtil.giveKeyItem(player, xi.keyItem.WINDURST_WOODS_SCOOP)\n        player:setCharVar('QuestMakingHeadlines_var', utils.mask.setBit(player:getCharVar('QuestMakingHeadlines_var'), 3, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Wani_Casdohry.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Wani_Casdohry.lua",["SHA256"]="9e9ce97a69a7d06b9167167fb4403fe69019a9e17f20a824d59099e3d0a4244e",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Wani Casdohry\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local twinstoneBonding = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TWINSTONE_BONDING)\n    local mihgosAmigo = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO)\n\n    if twinstoneBonding == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(492, 0, 13360)\n    elseif twinstoneBonding == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(489, 0, 13360)\n    elseif mihgosAmigo == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(86, 0, 498)\n    else\n        player:startEvent(425)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Wetata.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Wetata.lua",["SHA256"]="4b57d7e5f2e2676fe380f5f913f051d6c97968dc0f992ab07b5597cb9d5c35ed",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Wetata\n-- Trust NPC\n-- !pos -23.825 2.533 -44.567 241\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WOODS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    xi.trust.onTradeCipher(player, trade, 862, 901, 902)\nend\n\nentity.onTrigger = function(player, npc)\n    local trustSandoria = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n    local trustBastok   = player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.TRUST_BASTOK)\n    local trustWindurst = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n\n    if\n        player:getMainLvl() >= 5 and\n        xi.settings.main.ENABLE_TRUST_QUESTS == 1 and\n        trustWindurst == xi.questStatus.QUEST_AVAILABLE\n    then\n        if\n            trustBastok == xi.questStatus.QUEST_AVAILABLE and\n            trustSandoria == xi.questStatus.QUEST_AVAILABLE\n        then\n            player:startEvent(863)\n        elseif\n            trustBastok == xi.questStatus.QUEST_COMPLETED or\n            trustSandoria == xi.questStatus.QUEST_COMPLETED\n        then\n            player:startEvent(867)\n        end\n    elseif player:hasKeyItem(xi.keyItem.GREEN_INSTITUTE_CARD) then\n        player:startEvent(864)\n    elseif trustWindurst == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(861)\n    else\n        player:startEvent(868)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if (csid == 863 or csid == 867) and option == 2 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n        npcUtil.giveKeyItem(player, xi.keyItem.GREEN_INSTITUTE_CARD)\n    elseif csid == 862 or csid == 902 then\n        local spellID = player:getLocalVar('TradingTrustCipher')\n        player:setLocalVar('TradingTrustCipher', 0)\n        player:addSpell(spellID, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, spellID)\n        player:tradeComplete()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Xarcabard/npcs/qm1.lua"]={["Path"]="scripts/zones/Xarcabard/npcs/qm1.lua",["SHA256"]="9a89fe92812b4ff0b4e466b6b6dcd47962466988467549f83cbb3e8e14c0f545",["Text"]="-----------------------------------\n-- Area: Xarcabard\n--  NPC: qm1 (???)\n-- Involved in Quests: The Three Magi\n-- !pos -331 -29 -49 112\n-----------------------------------\nlocal ID = zones[xi.zone.XARCABARD]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.FADED_CRYSTAL) and\n        not player:hasItem(xi.item.GLOWSTONE) and\n        npcUtil.popFromQM(player, npc, ID.mob.CHAOS_ELEMENTAL, { hide = 0 })\n    then\n        player:confirmTrade()\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if GetMobByID(ID.mob.CHAOS_ELEMENTAL):isSpawned() then\n        player:messageSpecial(ID.text.DO_NOT_SENSE)\n        return\n    end\n\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI) == xi.questStatus.QUEST_ACCEPTED then\n        player:messageSpecial(ID.text.SENSE_EVIL)\n        return\n    end\n\n    player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\nend\n\nreturn entity\n"},["scripts/zones/Yahse_Hunting_Grounds/npcs/Yahse_Wildflower.lua"]={["Path"]="scripts/zones/Yahse_Hunting_Grounds/npcs/Yahse_Wildflower.lua",["SHA256"]="6f257933e231e9881f7793007dc2c5cddc6c717954ff99ea894bad9e1e155064",["Text"]="-----------------------------------\n-- Area: Yahse Hunting Grounds\n--  NPC: Yahse Wildflower\n-- Involved in quest Children of the Rune\n-- pos 370.6285 0.6692 153.3728\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    -- CHILDREN OF THE RUNE\n    if player:getQuestStatus(xi.questLog.ADOULIN, xi.quest.id.adoulin.CHILDREN_OF_THE_RUNE) == xi.questStatus.QUEST_ACCEPTED then\n        npcUtil.giveKeyItem(player, xi.keyItem.YAHSE_WILDFLOWER_PETAL)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Yhoator_Jungle/npcs/qm3.lua"]={["Path"]="scripts/zones/Yhoator_Jungle/npcs/qm3.lua",["SHA256"]="0a3f4676ef53db43f2db894ee14a2f3744cbc13077979a2f060453241c6bd816",["Text"]="-----------------------------------\n-- Area: Yhoator Jungle\n--  NPC: ??? (qm3)\n-- Involved in Quest: True will\n-- !pos 203 0.1 82 124\n-----------------------------------\nlocal ID = zones[xi.zone.YHOATOR_JUNGLE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL) == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.OLD_TRICK_BOX)\n    then\n        if player:getCharVar('trueWillKilledNM') > 0 then\n            npcUtil.giveKeyItem(player, xi.keyItem.OLD_TRICK_BOX)\n            player:setCharVar('trueWillKilledNM', 0)\n        else\n            player:messageSpecial(ID.text.CHILL_RUNS_DOWN)\n            npcUtil.popFromQM(player, npc, { ID.mob.KAPPA_AKUSO, ID.mob.KAPPA_BONZE, ID.mob.KAPPA_BIWA }, { hide = 0 })\n        end\n    else\n        player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Yuhtunga_Jungle/npcs/Blue_Rafflesia.lua"]={["Path"]="scripts/zones/Yuhtunga_Jungle/npcs/Blue_Rafflesia.lua",["SHA256"]="d37a79592a0cdbf34e308a8726f80f4680463b1bee3b2aade5eaa54e84e5a3f1",["Text"]="-----------------------------------\n-- Area: Yuhtunga Jungle\n--  NPC: Blue Rafflesia\n-- Used in quest Even More Gullible Travels\n-- !pos -468.876 -1 220.247 123 <many>\n-----------------------------------\nlocal ID = zones[xi.zone.YUHTUNGA_JUNGLE]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local evenmoreTravelsStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS)\n    local questprogress = player:getCharVar('EVEN_MORE_GULLIBLES_PROGRESS')\n    local scentDay = player:getCharVar('RafflesiaScentDay')\n    local currentDay = VanadielUniqueDay()\n    local scentReady = scentDay < currentDay\n    local offset = npc:getID() - ID.npc.BLUE_RAFFLESIA_OFFSET\n\n    if offset == 0 then\n        if\n            evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n            questprogress == 1 and\n            player:getCharVar('FirstBlueRafflesiaCS') == 0\n        then\n            -- Player is on quest, first time.\n            player:startEvent(21)\n        elseif\n            evenmoreTravelsStatus == xi.questStatus.QUEST_COMPLETED and\n            scentReady and\n            player:getCharVar('BathedInScent') == 0 and\n            player:getCharVar('FirstBlueRafflesiaCS') == 0\n        then\n            -- Repeating\n            player:startEvent(21)\n        else\n            player:messageSpecial(ID.text.FLOWER_BLOOMING)\n        end\n    elseif offset == 1 then\n        if\n            evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n            questprogress == 1 and\n            player:getCharVar('SecondBlueRafflesiaCS') == 0\n        then\n            player:startEvent(22)\n        elseif\n            evenmoreTravelsStatus == xi.questStatus.QUEST_COMPLETED and\n            scentReady and\n            player:getCharVar('BathedInScent') == 0 and\n            player:getCharVar('SecondBlueRafflesiaCS') == 0\n        then\n            player:startEvent(22)\n        else\n            player:messageSpecial(ID.text.FLOWER_BLOOMING)\n        end\n    elseif offset == 2 then\n        if\n            evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n            questprogress == 1 and\n            player:getCharVar('ThirdBlueRafflesiaCS') == 0\n        then\n            player:startEvent(23)\n        elseif\n            evenmoreTravelsStatus == xi.questStatus.QUEST_COMPLETED and\n            scentReady and\n            player:getCharVar('BathedInScent') == 0 and\n            player:getCharVar('ThirdBlueRafflesiaCS') == 0\n        then\n            player:startEvent(23)\n        else\n            player:messageSpecial(ID.text.FLOWER_BLOOMING)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    local evenmoreTravelsStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS)\n\n    -- Set BathedInScent to 1 if they touched all 3 Rafflesia for EVEN_MORE_GULLIBLES_TRAVELS which opens the quest The Opo-Opo and I\n    if csid == 21 and option == 1 then\n        -- This is 3rd Rafflessia clicked, progressing.\n        if\n            player:getCharVar('SecondBlueRafflesiaCS') == 1 and\n            player:getCharVar('ThirdBlueRafflesiaCS') == 1\n        then\n            player:setCharVar('SecondBlueRafflesiaCS', 0)\n            player:setCharVar('ThirdBlueRafflesiaCS', 0)\n            player:setCharVar('BathedInScent', 1)\n            player:setCharVar('RafflesiaScentDay', VanadielUniqueDay())\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n            player:messageSpecial(ID.text.FEEL_DIZZY) -- You feel slightly dizzy. You must have breathed in too much of the pollen.\n            if evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED then\n                player:setCharVar('EVEN_MORE_GULLIBLES_PROGRESS', 2)\n            end\n        else\n            player:setCharVar('FirstBlueRafflesiaCS', 1)\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n        end\n    elseif csid == 22 and option == 1 then\n        if\n            player:getCharVar('FirstBlueRafflesiaCS') == 1 and\n            player:getCharVar('ThirdBlueRafflesiaCS') == 1\n        then\n            player:setCharVar('FirstBlueRafflesiaCS', 0)\n            player:setCharVar('ThirdBlueRafflesiaCS', 0)\n            player:setCharVar('BathedInScent', 1)\n            player:setCharVar('RafflesiaScentDay', VanadielUniqueDay())\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n            player:messageSpecial(ID.text.FEEL_DIZZY) -- You feel slightly dizzy. You must have breathed in too much of the pollen.\n            if evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED then\n                player:setCharVar('EVEN_MORE_GULLIBLES_PROGRESS', 2)\n            end\n        else\n            player:setCharVar('SecondBlueRafflesiaCS', 1)\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n        end\n    elseif csid == 23 and option == 1 then\n        if\n            player:getCharVar('FirstBlueRafflesiaCS') == 1 and\n            player:getCharVar('SecondBlueRafflesiaCS') == 1\n        then\n            player:setCharVar('FirstBlueRafflesiaCS', 0)\n            player:setCharVar('SecondBlueRafflesiaCS', 0)\n            player:setCharVar('BathedInScent', 1)\n            player:setCharVar('RafflesiaScentDay', VanadielUniqueDay())\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n            player:messageSpecial(ID.text.FEEL_DIZZY) -- You feel slightly dizzy. You must have breathed in too much of the pollen.\n            if evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED then\n                player:setCharVar('EVEN_MORE_GULLIBLES_PROGRESS', 2)\n            end\n        else\n            player:setCharVar('ThirdBlueRafflesiaCS', 1)\n            npcUtil.giveItem(player, xi.item.JAR_OF_RAFFLESIA_NECTAR)\n        end\n    end\nend\n\nreturn entity\n"}};
